// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.feedback.RuntimeFeedbackContract;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsAvailability;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * Public API, default store configuration: a completed evaluation whose runtime feedback changes nothing a planner
 * reads must not invalidate the plan cached for the next identical request. The first evaluation of a single-pattern
 * query teaches its leaf's exact fact and row posterior. Re-planned with that fact, the leaf is database-exact, so the
 * second evaluation publishes typed feedback (the observation clock ticks) that only rewrites the fact with the same
 * rows: the learned planning revision, and with it the cached decision's evidence, stays current.
 */
@Timeout(180)
class LmdbNoOpFeedbackPlanCacheTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "urn:no-op-feedback-plan-cache:";
	private static final IRI NAME = VF.createIRI(NS + "name");
	private static final IRI BORROWED_BY = VF.createIRI(NS + "borrowedBy");
	private static final String QUERY = "PREFIX ex: <" + NS + "> SELECT ?loan WHERE { ?loan ex:borrowedBy ?member }";

	@Test
	void secondEvaluationThatTeachesNothingKeepsTheCachedPlanCurrent(@TempDir Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (int index = 0; index < 5; index++) {
				connection.add(VF.createIRI(NS + "loan/" + index), BORROWED_BY, VF.createIRI(NS + "member/" + index));
			}
			for (int index = 0; index < 5000; index++) {
				connection.add(VF.createIRI(NS + "member/" + index), NAME, VF.createLiteral("Member " + index));
			}
			connection.commit();
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			LmdbTestUtil.awaitBackgroundMaintenance(store, 60, TimeUnit.SECONDS);
			LmdbEstimatorRuntime runtime = ((LmdbEvaluationStatistics) store.getSailStore()
					.getEvaluationStatistics()).estimatorRuntime();

			assertEquals(5L, evaluate(connection), "COVERAGE_PREREQUISITE: the first evaluation completes");
			// The first evaluation's feedback made the cached plan stale; wait until its refresh is the current entry.
			TupleExpr refreshed = (TupleExpr) LmdbPlannerAwait.awaitDetachedPlanRefresh(() -> explain(connection))
					.tupleExpr();
			RuntimeFeedbackContract leaf = leafContract(refreshed);
			LmdbRuntimeFeedbackDescriptor key = (LmdbRuntimeFeedbackDescriptor) leaf.descriptor();
			LmdbOperatorFeedbackStats feedback = runtime.feedback();
			assertTrue(leaf.admits(RuntimeFeedbackContract.DATABASE_EXACT),
					"COVERAGE_PREREQUISITE: re-planned with its exact fact, the leaf is database-exact");
			long rowObservations = rowObservations(feedback, key);
			long leoRevision = runtime.capturePlanningRevisions().leoRevision();
			long clock = feedback.observationClock();

			assertEquals(5L, evaluate(connection), "COVERAGE_PREREQUISITE: the second evaluation completes");
			TupleExpr next = (TupleExpr) explain(connection).tupleExpr();

			assertAll(
					() -> assertTrue(feedback.observationClock() > clock,
							"COVERAGE_PREREQUISITE: the second evaluation published typed runtime feedback"),
					() -> assertEquals(5.0d, feedback.exactCardinalityFact(key.logicalKey(), key.applicability()),
							0.0d, "COVERAGE_PREREQUISITE: the fact was rewritten with the same rows"),
					() -> assertEquals(rowObservations, rowObservations(feedback, key),
							"COVERAGE_PREREQUISITE: a database-exact leaf admits no row observation"),
					() -> assertEquals(leoRevision, runtime.capturePlanningRevisions().leoRevision(),
							"feedback that changes no planner-visible value must leave the LEO revision unchanged"),
					() -> assertEquals("USE", next.getStringMetricPlanned("optimizer.planCacheLookupOutcome"),
							"the next identical request must be served from the cache without a refresh; reason="
									+ next.getStringMetricPlanned("optimizer.planCacheRefreshReason")));
		} finally {
			repository.shutDown();
		}
	}

	private static long evaluate(SailRepositoryConnection connection) {
		long rows = 0L;
		try (TupleQueryResult result = connection.prepareTupleQuery(QUERY).evaluate()) {
			while (result.hasNext()) {
				result.next();
				rows++;
			}
		}
		return rows;
	}

	private static Explanation explain(SailRepositoryConnection connection) {
		return connection.prepareTupleQuery(QUERY).explain(Explanation.Level.Optimized);
	}

	private static RuntimeFeedbackContract leafContract(TupleExpr plan) {
		RuntimeFeedbackContract[] found = new RuntimeFeedbackContract[1];
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				RuntimeFeedbackContract contract = node.getRuntimeFeedbackContract();
				if (contract != null && contract.descriptor() instanceof LmdbRuntimeFeedbackDescriptor) {
					found[0] = contract;
				}
			}
		});
		assertNotNull(found[0], "COVERAGE_PREREQUISITE: the leaf carries a typed contract");
		return found[0];
	}

	private static long rowObservations(LmdbOperatorFeedbackStats feedback, LmdbRuntimeFeedbackDescriptor key) {
		FrontierLearningModel.PosteriorSnapshot posterior = feedback.logicalPosterior(key.logicalKey(),
				key.applicability(), FrontierCostDimension.OUTPUT_ROWS);
		return posterior == null ? 0L : posterior.exactEvidenceCount();
	}
}
